INSERT INTO `courses` VALUES (1,'Java Full Stack Development – Complete Bootcamp','java-full-stack-bootcamp','Master Java core, Spring Boot REST APIs, React frontend & PostgreSQL database integration.','A comprehensive full-stack engineering bootcamp taking you from core programming fundamentals to production-grade web application development. Learn Java 17+, Spring Boot microservices, JPA/Hibernate persistence, and React 18 frontend integration with real-world industry capstone projects.','Core Java 17+ with OOP principles\nSpring Boot REST API development\nRelational Database Design & SQL\nReact Frontend Integration\nJWT Authentication & Spring Security\nMicroservices Architecture\nDeployment & CI/CD Basics','Basic computer literacy\nNo prior programming experience required\nDedication to practical hands-on coding',9999.00,3999.00,'https://images.unsplash.com/photo-1517180102446-f3ece451e9d8?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','Hindi + English','BEGINNER',10,'120h 30m',4.8,2840,12500,1,1,1,'COURSE',1,1,'2026-09-16 23:38:05','2026-09-16 23:38:05',60),(2,'Spring Boot Microservices & Event-Driven Architecture','spring-boot-microservices-advanced','Build production-ready microservices with Spring Boot, Apache Kafka & Docker.','Deep dive into microservices architecture using Spring Cloud. Implement service discovery with Eureka, resilient API gateways, event-driven communication with Apache Kafka, distributed tracing, and Docker containerization for scalable enterprise applications.','Microservices architectural patterns\nSpring Cloud Gateway & Eureka Service Registry\nEvent-driven messaging using Apache Kafka\nResilience4j circuit breakers & rate limiting\nDocker containerization & docker-compose\nDistributed tracing with Zipkin & Micrometer','Strong Java fundamentals\nBasic Spring Boot understanding\nFamiliarity with REST APIs',7999.00,2999.00,'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','ADVANCED',8,'65h 00m',4.9,1560,8200,1,0,1,'COURSE',2,1,'2026-09-16 23:38:06','2026-09-16 23:38:06',63),(3,'React 18 & TypeScript – Modern Web Development','react-typescript-modern-web','Build high-performance web apps with React 18, TypeScript, Redux Toolkit & Tailwind CSS.','Master modern frontend development with React 18 and TypeScript. Learn functional component architecture, custom hooks, state management with Redux Toolkit and React Query, Tailwind CSS styling, unit testing with Vitest, and production deployment.','React 18 features & hooks lifecycle\nTypeScript strict typing for React\nGlobal state management with Redux Toolkit\nServer state fetching with React Query\nTailwind CSS responsive design\nUnit testing with Vitest & Testing Library','Basic HTML, CSS, JavaScript (ES6+)\nFamiliarity with web browsers and terminal',6999.00,2499.00,'https://images.unsplash.com/photo-1633356122544-f134324a6cee?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','INTERMEDIATE',8,'80h 00m',4.7,980,6400,1,1,1,'COURSE',4,4,'2026-09-16 23:38:06','2026-09-16 23:38:06',64),(4,'Python for Data Science & Applied Machine Learning','python-data-science-ml','Complete data science workflow: Python, Pandas, Data Visualization & ML Models.','From Python programming basics to building practical machine learning pipelines. Master NumPy, Pandas, Matplotlib, Seaborn, and Scikit-learn. Analyze real datasets, clean raw data, perform exploratory data analysis (EDA), and deploy predictive models.','Python programming & data structures\nData manipulation with Pandas & NumPy\nExploratory Data Analysis & Visualization\nSupervised machine learning algorithms\nModel validation & hyperparameter tuning\nDeploying ML models with Flask APIs','Basic high-school mathematics\nNo prior programming experience required',8499.00,3299.00,'https://images.unsplash.com/photo-1527474305487-b87b222841cc?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English + Hindi','BEGINNER',9,'95h 00m',4.9,3200,18000,1,1,1,'COURSE',5,2,'2026-09-16 23:38:06','2026-09-16 23:38:06',61),(5,'Machine Learning A-Z: AI & Deep Learning with Python','machine-learning-az-ai-python','Master ML algorithms, Neural Networks, Computer Vision & PyTorch.','An intensive machine learning masterclass covering supervised learning, unsupervised clustering, reinforcement learning, natural language processing (NLP), and deep neural networks using PyTorch and TensorFlow.','Regression, Classification & Clustering\nDeep Learning with PyTorch\nConvolutional Neural Networks (CNNs)\nNatural Language Processing (NLP)\nFeature engineering & dimensionality reduction\nModel evaluation metrics','Python programming basics\nLinear algebra and basic statistics concepts',5999.00,1999.00,'https://images.unsplash.com/photo-1555949963-ff9fe0c870eb?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','INTERMEDIATE',9,'72h 30m',4.8,2100,14000,0,1,1,'COURSE',7,2,'2026-09-16 23:38:06','2026-09-16 23:43:00',67),(6,'AWS Cloud Practitioner & Solutions Architect Masterclass','aws-cloud-solutions-architect','Design resilient, scalable, and secure cloud infrastructure on Amazon Web Services.','Master core AWS services including EC2, S3, RDS, Lambda serverless, VPC networking, IAM security, and CloudFront. Prepare effectively for AWS certifications while building practical cloud infrastructure architectures.','AWS Infrastructure & IAM security policies\nVirtual Private Cloud (VPC) networking\nEC2 compute instances & Auto Scaling\nS3 object storage & RDS databases\nServerless computing with AWS Lambda\nCloudWatch monitoring & cost optimization','Basic understanding of networking and operating systems\nNo prior cloud experience needed',8999.00,3599.00,'https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','INTERMEDIATE',9,'54h 00m',4.6,640,4100,1,0,1,'COURSE',8,5,'2026-09-16 23:38:06','2026-09-16 23:43:00',60),(7,'DevOps Engineering: Docker, Kubernetes & CI/CD Pipelines','devops-docker-kubernetes-cicd','Automate deployment workflows with Docker, Kubernetes, GitHub Actions & Terraform.','Learn modern DevOps automation. Build multi-stage Docker images, orchestrate container workloads using Kubernetes deployments and services, automate continuous integration and delivery with GitHub Actions, and manage infrastructure as code with Terraform.','Docker containerization & multi-stage builds\nKubernetes pods, services, deployments & ingress\nCI/CD automated pipelines with GitHub Actions\nInfrastructure as Code using Terraform\nMonitoring with Prometheus & Grafana\nSecurity compliance in DevOps pipelines','Linux terminal basics\nUnderstanding of web application architecture',7499.00,2899.00,'https://images.unsplash.com/photo-1618401471353-b98afee0b2eb?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','ADVANCED',9,'48h 30m',4.7,420,2800,0,1,1,'COURSE',9,5,'2026-09-16 23:38:06','2026-09-16 23:43:00',61),(8,'Cybersecurity Fundamentals & Ethical Hacking Hands-On','cybersecurity-ethical-hacking','Protect networks, applications, and data with practical defense strategies.','Gain foundational knowledge in cybersecurity principles, network security protocols, vulnerability scanning, web application security (OWASP Top 10), penetration testing techniques, and risk management framework.','Network protocols & Wireshark packet analysis\nOWASP Top 10 web security vulnerabilities\nVulnerability scanning with Nmap & Nessus\nCryptography basics & public key infrastructure\nIncident response & risk mitigation strategies','Basic computer networks understanding\nPassion for security and ethical hacking',6499.00,2199.00,'https://images.unsplash.com/photo-1563986768609-322da13575f3?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','BEGINNER',9,'40h 15m',4.5,310,1950,0,0,1,'COURSE',10,5,'2026-09-16 23:38:06','2026-09-16 23:43:00',66),(9,'Leadership Masterclass: Executive Presence & High-Performing Teams','leadership-masterclass','Transform your leadership style, inspire teams, and drive strategic organizational execution.','Essential leadership capabilities for current and aspiring managers. Learn situational leadership models, emotional intelligence, conflict resolution, team motivation frameworks, strategic decision-making, and workplace culture building.','Situational leadership & adaptive management styles\nEmotional intelligence in executive decision-making\nConflict resolution & constructive feedback\nBuilding & motivating high-performing remote/hybrid teams\nStrategic thinking & stakeholder alignment','Open to professionals, managers, and team leaders\nNo specific technical background required',4999.00,1799.00,'https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','BEGINNER',9,'42h 00m',4.7,890,7500,1,0,1,'COURSE',12,3,'2026-09-16 23:38:06','2026-09-16 23:43:00',64),(10,'Business Management & Corporate Strategy','business-management-fundamentals','Practical business management, organizational behavior & strategic planning.','Comprehensive overview of practical business operations and strategic management. Covers organizational planning, competitive analysis, business model innovation, operations management, and performance measurement frameworks.','Business strategic analysis & SWOT framework\nOrganizational structure & management design\nOperational efficiency & process optimization\nBusiness financial fundamentals for managers\nChange management & innovation strategy','No prior business experience required\nIdeal for entrepreneurs & professionals',3999.00,1499.00,'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English + Hindi','BEGINNER',9,'35h 00m',4.6,640,5200,0,1,1,'COURSE',11,3,'2026-09-16 23:38:06','2026-09-16 23:43:00',63),(11,'Agile Project Management & Scrum Master Certification Guide','agile-project-management-scrum','Master Scrum ceremonies, sprint planning, Kanban & Agile delivery execution.','Master Agile project management principles and Scrum implementation. Learn user story mapping, backlog grooming, sprint planning, velocity tracking, burn-down metrics, and Agile transformation leadership for software and business teams.','Agile Manifesto & core Scrum values\nScrum Roles: Product Owner, Scrum Master, Developers\nSprint Planning, Daily Standup, Review & Retrospective\nUser Story estimation & Product Backlog refinement\nKanban workflow management & WIP limits\nAgile metrics & team velocity tracking','No prerequisites\nSuitable for project managers, software engineers, and product leads',5499.00,1999.00,'https://images.unsplash.com/photo-1531403009284-440f080d1e12?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','INTERMEDIATE',9,'38h 45m',4.8,1120,6800,1,1,1,'COURSE',15,3,'2026-09-16 23:38:06','2026-09-16 23:43:00',64),(12,'Digital Marketing Strategy & Data-Driven Growth','digital-marketing-growth-strategy','Drive customer acquisition through SEO, content marketing, PPC & analytics.','Learn modern data-driven digital marketing. Covers search engine optimization (SEO), performance marketing on Google Ads & Meta, content strategy, email marketing funnels, conversion rate optimization (CRO), and Google Analytics 4 tracking.','Search Engine Optimization (SEO) fundamentals\nPerformance advertising on Google & Social Media\nContent marketing strategy & brand messaging\nConversion rate optimization & A/B testing\nGoogle Analytics 4 setup & growth attribution','Basic familiarity with social media & web tools\nNo mathematical background required',4499.00,1699.00,'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','BEGINNER',9,'32h 00m',4.4,280,1850,0,0,1,'COURSE',13,3,'2026-09-16 23:38:06','2026-09-16 23:43:00',62),(13,'Corporate Financial Analysis & Valuation Modeling','corporate-financial-analysis-valuation','Master financial statements, DCF valuation modeling, and capital budgeting.','Master financial analysis and valuation modeling for corporate finance decision-making. Learn income statement, balance sheet, and cash flow analysis, financial ratio modeling, discounted cash flow (DCF) valuation, and capital budgeting principles.','Financial statement analysis & forecasting\nFinancial ratio benchmarking & profitability metrics\nDiscounted Cash Flow (DCF) valuation modeling\nCapital budgeting, NPV & IRR decision models\nWorking capital management fundamentals','Basic Excel understanding\nInterest in business finance and accounting',6999.00,2699.00,'https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','INTERMEDIATE',9,'44h 20m',4.6,195,1250,0,0,1,'COURSE',14,3,'2026-09-16 23:38:06','2026-09-16 23:43:00',61),(14,'Product Management: Strategy, Discovery & Launch Roadmap','product-management-strategy-discovery','From customer problem discovery to product strategy, wireframing & launch.','Learn the end-to-end product management lifecycle. Master user research, problem validation, product vision definition, PRD documentation, feature prioritization frameworks (RICE, Kano), wireframing, UX collaboration, and product launch execution.','Product vision, strategy & North Star metric\nUser research & problem discovery interviews\nProduct Requirement Document (PRD) writing\nFeature prioritization (RICE & Kano frameworks)\nWireframing & working with UI/UX designers\nProduct launch checklist & GTM strategy','Interest in building digital products\nNo technical coding background required',7999.00,2999.00,'https://images.unsplash.com/photo-1507238691740-187a5b1d37b8?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','INTERMEDIATE',9,'50h 00m',4.8,750,4600,1,1,1,'COURSE',17,3,'2026-09-16 23:38:06','2026-09-16 23:43:01',63),(15,'Full Stack Web Development with MERN Stack','full-stack-web-mern','Build full-stack web applications with MongoDB, Express.js, React, and Node.js.','Complete MERN stack developer track. Build scalable RESTful APIs with Node.js and Express, store document data using MongoDB and Mongoose, craft dynamic frontend interfaces with React, implement JWT security, and deploy to Vercel and cloud servers.','Node.js event loop & Express.js middleware\nMongoDB document design & Mongoose schemas\nReact state management & custom hooks\nRESTful API architecture & error handling\nJWT authentication & protected routes\nDeploying MERN applications to cloud hosting','HTML, CSS, JavaScript fundamentals\nBasic understanding of programming logic',7499.00,2799.00,'https://images.unsplash.com/photo-1593720213428-28a5b9e94613?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','INTERMEDIATE',9,'85h 00m',4.8,1750,9800,0,1,1,'COURSE',3,4,'2026-09-16 23:38:06','2026-09-16 23:38:06',63),(16,'Data Analytics & Business Intelligence with SQL & Tableau','data-analytics-sql-tableau','Turn raw business data into actionable dashboard insights with SQL and Tableau.','Learn end-to-end data analytics for business intelligence. Master complex SQL queries (JOINs, Window functions, aggregations), data transformation, storytelling with data, and creating interactive executive dashboards using Tableau.','Advanced SQL querying & window functions\nData cleaning & transformation techniques\nExploratory business data analysis\nDesigning interactive dashboards in Tableau\nData storytelling & executive presentation','Basic computer literacy & working with Excel\nNo prior coding experience required',6499.00,2299.00,'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=800&auto=format&fit=crop&q=60','/assets/videos/sample-course-preview.mp4','English','BEGINNER',9,'46h 30m',4.7,510,3400,0,0,1,'COURSE',6,2,'2026-09-16 23:38:06','2026-09-16 23:43:01',65),(17,'Java Programming Masterclass','java-programming-masterclass','Master core Java 17+, OOP, Collections, Lambda Expressions & Exception Handling.','Complete Java development masterclass for beginners and professionals. Master object-oriented programming, modern Java 17/21 language features, memory management, multithreading, and stream API.','Core Java Syntax & OOP Principles\nCollections Framework & Generics\nLambda Expressions & Stream API\nException Handling & File I/O\nMultithreading & Concurrency','No prior programming experience required\nBasic computer operation literacy',3499.00,1499.00,'https://images.unsplash.com/photo-1517180102446-f3ece451e9d8?w=800&auto=format&fit=crop&q=60','https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4','Hindi + English','BEGINNER',12,'42h 30m',4.8,2450,14200,1,1,1,'TECHNOLOGY',1,1,'2026-09-17 15:57:53','2026-09-17 23:09:36',57),(18,'Advanced Java Development','advanced-java-development','Master Java Concurrency, JVM Internals, Memory Management & Garbage Collection.','Deep dive into advanced Java concepts. Understand JVM architecture, garbage collection tuning, java.util.concurrent locks, CompletableFuture asynchronous patterns, and bytecode optimization.','JVM Memory Model & GC Tuning\nAdvanced Multithreading & Locks\nCompletableFuture & Reactive Streams\nJava Reflection & Dynamic Proxies\nDesign Patterns in Java','Solid understanding of core Java OOP concepts\nExperience writing basic Java applications',5499.00,2499.00,'https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=800&auto=format&fit=crop&q=60','https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ElephantsDream.mp4','English','ADVANCED',10,'36h 15m',4.9,1180,6800,0,1,1,'TECHNOLOGY',1,1,'2026-09-17 15:57:53','2026-09-17 23:09:36',55),(19,'Java Collections & Generics','java-collections-generics','Deep dive into List, Set, Map, Queue, Wildcards & Custom Data Structures.','In-depth analysis of the Java Collections Framework. Learn internal data structure mechanics of ArrayList, HashMap, ConcurrentHashMap, PriorityQueue, and custom generic classes.','Internal working of HashMap & HashSet\nCustom Generic classes & Wildcards (? extends T)\nConcurrent & Synchronized Collections\nPerformance Benchmarking & Big-O\nBest practices for collection choices','Basic Java programming knowledge',2499.00,999.00,'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?w=800&auto=format&fit=crop&q=80','https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4','English','INTERMEDIATE',8,'18h 45m',4.7,850,5200,0,0,1,'TECHNOLOGY',1,1,'2026-09-17 15:57:53','2026-09-17 23:09:36',60),(20,'Spring Boot & REST API Development','spring-boot-rest-api-dev','Build robust, production-ready RESTful web services with Spring Boot 3 & JPA.','Learn enterprise backend engineering with Spring Boot 3. Master REST controller design, DTO mapping, Spring Data JPA, database migrations with Flyway, error handling, and Swagger API docs.','Spring Boot 3 Core Annotations\nREST API Design & Exception Handling\nSpring Data JPA & Hibernate Repository\nDTO Pattern & MapStruct Mapping\nSwagger / OpenAPI 3 Documentation','Basic Java programming knowledge\nUnderstanding of HTTP protocols',4499.00,1999.00,'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=800&auto=format&fit=crop&q=60','https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4','Hindi + English','INTERMEDIATE',11,'52h 00m',4.9,3200,16400,1,1,1,'TECHNOLOGY',2,1,'2026-09-17 15:57:53','2026-09-17 23:09:36',56),(21,'Spring Security & JWT','spring-security-jwt','Secure enterprise REST APIs using OAuth2, Spring Security 6, JWT & RBAC.','Comprehensive security guide for Java applications. Implement stateless JWT token authentication, refresh tokens, Role-Based Access Control (RBAC), Method Security, CORS, and CSRF protection.','Spring Security 6 Architecture\nStateless JWT Authentication Flow\nRole-Based Access Control (RBAC)\nPassword Hashing with BCrypt\nSecurity Filters & Exception Handling','Working knowledge of Spring Boot REST APIs',3999.00,1699.00,'https://images.unsplash.com/photo-1563986768609-322da13575f3?w=800&auto=format&fit=crop&q=60','https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerFun.mp4','English','ADVANCED',9,'28h 30m',4.8,1650,9100,0,1,1,'TECHNOLOGY',2,1,'2026-09-17 15:57:53','2026-09-17 23:09:36',57),(22,'Hibernate & JPA Masterclass','hibernate-jpa-masterclass','Master Object-Relational Mapping, Entity Relationships, N+1 Problem & Caching.','Master database persistence with JPA and Hibernate. Learn entity mapping, inheritance strategies, composite keys, criteria API, lazy vs eager fetching, N+1 query problem, and L2 cache.','JPA Entity Mappings & Relationships\nSolving the N+1 Query Problem\nJPQL & Criteria API Queries\nHibernate Second-Level Caching\nTransaction Isolation & Locking','Basic SQL knowledge\nBasic Java programming experience',3499.00,1499.00,'https://images.unsplash.com/photo-1544383835-bda2bc66a55d?w=800&auto=format&fit=crop&q=60','https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerJoyrides.mp4','English','INTERMEDIATE',8,'26h 00m',4.7,940,5800,0,0,1,'TECHNOLOGY',1,1,'2026-09-17 15:57:53','2026-09-17 23:09:36',57),(23,'Microservices with Spring Boot','microservices-spring-boot','Build scalable microservices with Spring Cloud, Eureka, Gateway & Kafka.','Architect resilient distributed microservices using Spring Cloud. Implement Eureka Service Registry, API Gateway, Resilience4j Circuit Breakers, Apache Kafka event streams, and Docker containerization.','Microservices Architectural Principles\nService Discovery with Spring Cloud Eureka\nAPI Gate